ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
"error": {
"code": vars.httpStatus default 500 as String,
"message": error.errorMessage default "Internal Server Error",
"description": "Error handler failed: " ++ (error.description default "Description unavailable."),
"type": (error.errorType.namespace ++ ":" ++ error.errorType.identifier) default "HANDLER:INTERNAL",
"component": error.failingComponent default "Unknown",
"timestamp": now(),
"correlationId": correlationId
}}

